import React, { useState } from "react";
import "./StaffDashboard.css";

const StaffDashboard = () => {
  const [activePage, setActivePage] = useState("home");

  // 🧩 Dummy Data
  const mentees = [
    { name: "Aarav", email: "aarav@school.com", points: 120 },
    { name: "Diya", email: "diya@school.com", points: 95 },
    { name: "Rohan", email: "rohan@school.com", points: 150 },
  ];

  const gameStats = [
    { name: "Aarav", game: "Eco Maze", points: 45 },
    { name: "Diya", game: "Knowledge Flip", points: 30 },
    { name: "Rohan", game: "Water Leak", points: 60 },
  ];

  const videoStats = [
    { name: "Aarav", video: "Recycling 101", time: "15 min" },
    { name: "Diya", video: "Saving Trees", time: "10 min" },
    { name: "Rohan", video: "Wildlife Wonders", time: "25 min" },
  ];

  const quizStats = [
    { name: "Aarav", quiz: "Eco Quiz 1", score: 8 },
    { name: "Diya", quiz: "Eco Quiz 2", score: 6 },
    { name: "Rohan", quiz: "Eco Quiz 1", score: 9 },
  ];

  const handleLogout = () => {
    localStorage.clear();
    window.location.href = "/login";
  };

  const renderPage = () => {
    switch (activePage) {
      case "home":
        return (
          <div className="content-card">
            <h2>Your Mentees List</h2>
            <select className="mentee-dropdown">
              <option>Select a Mentee</option>
              {mentees.map((m, i) => (
                <option key={i}>
                  {m.name} — {m.email} ({m.points} pts)
                </option>
              ))}
            </select>
          </div>
        );

      case "games":
        return (
          <div className="content-card">
            <h2>Games Overview</h2>
            <table>
              <thead>
                <tr>
                  <th>Student</th>
                  <th>Game</th>
                  <th>Points</th>
                </tr>
              </thead>
              <tbody>
                {gameStats.map((g, i) => (
                  <tr key={i}>
                    <td>{g.name}</td>
                    <td>{g.game}</td>
                    <td>{g.points}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        );

      case "videos":
        return (
          <div className="content-card">
            <h2>Learning Videos Progress</h2>
            <table>
              <thead>
                <tr>
                  <th>Student</th>
                  <th>Video</th>
                  <th>Time Spent</th>
                </tr>
              </thead>
              <tbody>
                {videoStats.map((v, i) => (
                  <tr key={i}>
                    <td>{v.name}</td>
                    <td>{v.video}</td>
                    <td>{v.time}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        );

      case "quizzes":
        return (
          <div className="content-card">
            <h2>Quiz Results</h2>
            <table>
              <thead>
                <tr>
                  <th>Student</th>
                  <th>Quiz</th>
                  <th>Score</th>
                </tr>
              </thead>
              <tbody>
                {quizStats.map((q, i) => (
                  <tr key={i}>
                    <td>{q.name}</td>
                    <td>{q.quiz}</td>
                    <td>{q.score}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        );

      default:
        return null;
    }
  };

  return (
    <div className="dashboard-container">
      <aside className="sidebar">
        <div className="sidebar-logo">NEXORA</div>
        <nav>
          <ul>
            <li onClick={() => setActivePage("home")} className={activePage === "home" ? "active" : ""}>Home</li>
            <li onClick={() => setActivePage("games")} className={activePage === "games" ? "active" : ""}>Games</li>
            <li onClick={() => setActivePage("videos")} className={activePage === "videos" ? "active" : ""}>Learning Videos</li>
            <li onClick={() => setActivePage("quizzes")} className={activePage === "quizzes" ? "active" : ""}>Quizzes</li>
            <li onClick={handleLogout}>Logout</li>
          </ul>
        </nav>
      </aside>

      <main className="dashboard-main">{renderPage()}</main>
    </div>
  );
};

export default StaffDashboard;
